            { "chainId", chainId },
            { "name", "HyperliquidSignTransaction" },
            { "verifyingContract", zeroAddress },
            { "version", "1" },
        };
        byte[] msg = this.ethEncodeStructuredData(domain, messageTypes, message);
        object signature = this.signMessage(msg, this.privateKey);
        return signature;
    }

