    public override Dictionary<string, object> parseOrder(object order, IDictionary<string, object> market = null)
    {
        //
        // createOrdersWs error
        //
        //  {error: 'Insufficient margin to place order. asset=159'}
        //
        //  fetchOpenOrders
        //
        //     {
        //         "coin": "ETH",
        //         "limitPx": "2000.0",
        //         "oid": 3991946565,
        //         "origSz": "0.1",
        //         "side": "B",
        //         "sz": "0.1",
        //         "timestamp": 1704346468838
        //     }
        // fetchClosedorders
        //    {
        //        "cloid": null,
        //        "closedPnl": "0.0",
        //        "coin": "SOL",
        //        "crossed": true,
        //        "dir": "Open Long",
        //        "fee": "0.003879",
        //        "hash": "0x4a2647998682b7f07bc5040ab531e1011400f9a51bfa0346a0b41ebe510e8875",
        //        "liquidationMarkPx": null,
        //        "oid": "6463280784",
        //        "px": "110.83",
        //        "side": "B",
        //        "startPosition": "1.64",
        //        "sz": "0.1",
        //        "tid": "232174667018988",
        //        "time": "1709142268394"
        //    }
        //
        //  fetchOrder
        //
        //     {
        //         "order": {
        //             "children": [],
        //             "cloid": null,
        //             "coin": "ETH",
        //             "isPositionTpsl": false,
        //             "isTrigger": false,
        //             "limitPx": "2000.0",
        //             "oid": "3991946565",
        //             "orderType": "Limit",
        //             "origSz": "0.1",
        //             "reduceOnly": false,
        //             "side": "B",
        //             "sz": "0.1",
        //             "tif": "Gtc",
        //             "timestamp": "1704346468838",
        //             "triggerCondition": "N/A",
        //             "triggerPx": "0.0"
        //         },
        //         "status": "open",
        //         "statusTimestamp": "1704346468838"
        //     }
        //
        // createOrder
        //
        //     {
        //         "resting": {
        //             "oid": 5063830287
        //         }
        //     }
        //
        //     {
        //        "filled":{
        //           "totalSz":"0.1",
        //           "avgPx":"100.84",
        //           "oid":6195281425
        //        }
        //     }
        // frontendOrder
        // {
        //     "children": [],
        //     "cloid": null,
        //     "coin": "BLUR",
        //     "isPositionTpsl": false,
        //     "isTrigger": true,
        //     "limitPx": "0.5",
        //     "oid": 8670487141,
        //     "orderType": "Stop Limit",
        //     "origSz": "20.0",
        //     "reduceOnly": false,
        //     "side": "B",
        //     "sz": "20.0",
        //     "tif": null,
        //     "timestamp": 1715523663687,
        //     "triggerCondition": "Price above 0.6",
        //     "triggerPx": "0.6"
        // }
        //
        string? error = this.safeString(order, "error");
        if ((error != null))
        {
            object finalOrder = order; // java req
            return this.safeOrder(new Dictionary<string, object>() {
                { "info", finalOrder },
                { "status", "rejected" },
            });
        }
        object entry = this.safeDictN(order, new List<object>() {"order", "resting", "filled"});
        if ((entry == null))
        {
            entry = order;
        }
        IDictionary<string, object> filled = this.safeDict(order, "filled", new Dictionary<string, object>() {});
        string? coin = this.safeString(entry, "coin");
        string? marketId = null;
        if ((coin != null))
        {
            marketId = this.coinToMarketId(coin);
        }
        IDictionary<string, object> marketResolved = null;
        if ((this.safeString(entry, "id") == null))
        {
            marketResolved = this.safeMarket(marketId);
        } else
        {
            marketResolved = this.safeMarket(marketId, market);
        }
        string? symbol = ((string)GetValue(marketResolved, "symbol"));
        Int64? timestamp = this.safeInteger(entry, "timestamp");
        string? status = this.safeString2(order, "status", "ccxtStatus");
        object orderOmitted = this.omit(order, new List<object>() {"ccxtStatus"});
        string? side = this.safeString(entry, "side");
        if ((side != null))
        {
            side = (side == "A") ? "sell" : "buy";
        }
        string? totalAmount = this.safeString2(entry, "origSz", "totalSz");
        string? remaining = this.safeString(entry, "sz");
        string? tif = this.safeStringUpper(entry, "tif");
        bool? postOnly = null;
        if ((tif != null))
        {
            postOnly = (tif == "ALO");
        }
        bool isTrigger = ((this.safeBool(entry, "isTrigger") == true));
        double? triggerPx = isTrigger ? this.safeNumber(entry, "triggerPx") : null;
        // standalone stop / take-profit orders carry their trigger in triggerPx - surface it
        // through the unified stopLossPrice / takeProfitPrice fields as well, see #24318
        string orderTypeRaw = this.safeStringLower(entry, "orderType", "");
        double? stopLossPrice = null;
        double? takeProfitPrice = null;
        if ((triggerPx != null))
        {
            if (orderTypeRaw.IndexOf("stop", StringComparison.Ordinal) >= 0)
            {
                stopLossPrice = triggerPx;
            } else if (orderTypeRaw.IndexOf("take profit", StringComparison.Ordinal) >= 0)
            {
                takeProfitPrice = triggerPx;
            }
        }
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", orderOmitted },
            { "id", this.safeString(entry, "oid") },
            { "clientOrderId", this.safeString(entry, "cloid") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "lastUpdateTimestamp", this.safeInteger(orderOmitted, "statusTimestamp") },
            { "symbol", symbol },
            { "type", this.parseOrderType(this.safeStringLower(entry, "orderType")) },
            { "timeInForce", tif },
            { "postOnly", postOnly },
            { "reduceOnly", this.safeBool(entry, "reduceOnly") },
            { "side", side },
            { "price", this.safeString(entry, "limitPx") },
            { "triggerPrice", triggerPx },
            { "stopLossPrice", stopLossPrice },
            { "takeProfitPrice", takeProfitPrice },
            { "amount", totalAmount },
            { "cost", null },
            { "average", this.safeString(entry, "avgPx") },
            { "filled", this.safeString(filled, "totalSz", Precise.stringSub(totalAmount, remaining)) },
            { "remaining", remaining },
            { "status", this.parseOrderStatus(status) },
            { "fee", null },
            { "trades", null },
        }, marketResolved);
    }

    public virtual string? parseOrderStatus(string? status)
    {
        if ((status == null))
        {
            return null;
        }
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "triggered", "open" },
            { "filled", "closed" },
            { "open", "open" },
            { "canceled", "canceled" },
            { "rejected", "rejected" },
            { "marginCanceled", "canceled" },
        };
        if (status.EndsWith("Rejected"))
        {
            return "rejected";
        }
        if (status.EndsWith("Canceled"))
        {
            return "canceled";
        }
        return this.safeString(statuses, status, status);
    }

    public virtual string? parseOrderType(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "stop limit", "limit" },
            { "stop market", "market" },
        };
        return this.safeString(statuses, status, status);
    }

