        }
        string url = ((this.implodeHostname(apiUrl) + "/") + path);
        bool isPost = ((method == "POST"));
        Dictionary<string, object> postHeaders = new Dictionary<string, object>() {
            { "Content-Type", "application/json" },
        };
        object requestHeaders = headers;
        if (isPost)
        {
